package scenariosdocs

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// revisionFileFormat is the whole of revision.go, so that bumping the pin can
// never leave the file half-written.
const revisionFileFormat = `package scenariosdocs

// Code generated by "go run -C tools ./cmd scenarios-docs bump". DO NOT EDIT.

// revision is the grafana/alloy-scenarios commit that the scenario tables in
// docs/sources/shared/scenarios are generated from.
const revision = %q
`

// writeRevision rewrites the file that pins the alloy-scenarios commit.
func writeRevision(path, sha string) error {
	if err := validateSHA(sha); err != nil {
		return err
	}
	if err := os.WriteFile(path, []byte(fmt.Sprintf(revisionFileFormat, sha)), 0o644); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	return nil
}

// resolveMainSHA returns the current commit of the main branch of the
// alloy-scenarios repository. It uses git so that no API token is needed.
func resolveMainSHA(ctx context.Context) (string, error) {
	out, err := exec.CommandContext(ctx, "git", "ls-remote",
		"https://github.com/"+repoSlug+".git", "refs/heads/main").Output()
	if err != nil {
		return "", fmt.Errorf("resolve main branch of %s: %w", repoSlug, err)
	}

	fields := strings.Fields(string(out))
	if len(fields) == 0 {
		return "", errors.New("git ls-remote returned no output for refs/heads/main")
	}
	if err := validateSHA(fields[0]); err != nil {
		return "", fmt.Errorf("unexpected git ls-remote output: %w", err)
	}
	return fields[0], nil
}
